import { beforeEach, describe, expect, it, vi } from "vitest";
import { readSendingActive } from "@/lib/sending-status";
import { getSendingActive } from "@/lib/sending-status-actions";

const { findFirst, auth } = vi.hoisted(() => ({
  findFirst: vi.fn(),
  auth: vi.fn(),
}));
vi.mock("@/lib/db", () => ({ db: { send: { findFirst } } }));
vi.mock("@/auth", () => ({ auth }));
beforeEach(() => vi.resetAllMocks());

describe("sending status", () => {
  it("authenticates before reading sending status", async () => {
    auth.mockResolvedValue(null);
    await expect(getSendingActive()).rejects.toThrow("Unauthenticated");
    expect(findFirst).not.toHaveBeenCalled();
  });
  it("scopes status to the session user and excludes uncertain deliveries", async () => {
    auth.mockResolvedValue({ user: { id: "session-user" } });
    findFirst.mockResolvedValue({ id: "active-send" });
    await expect(getSendingActive()).resolves.toBe(true);
    expect(findFirst).toHaveBeenCalledWith({
      where: {
        campaign: { userId: "session-user" },
        status: "QUEUED",
        deliveryState: { not: "UNCERTAIN" },
      },
      select: { id: true },
    });
  });
  it("does not redirect or query deliveries after account access is revoked", async () => {
    auth.mockResolvedValue({ user: { id: "" } });
    await expect(getSendingActive()).rejects.toThrow("Unauthenticated");
    expect(findFirst).not.toHaveBeenCalled();
  });
  it("unlocks only after a successful lookup finds no active delivery", async () => {
    findFirst.mockResolvedValue(null);
    await expect(readSendingActive("session-user")).resolves.toBe(false);
    findFirst.mockRejectedValue(new Error("Database unavailable"));
    await expect(readSendingActive("session-user")).rejects.toThrow(
      "Database unavailable",
    );
  });
});
